/* ══════════════════════════════════════
   LoadingDialog — 시간 기반 로딩 UI
   ══════════════════════════════════════ */

/* 오버레이 */
.loading-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.52);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}

/* 카드 */
.loading-box {
  background: #fff;
  border-radius: 20px;
  padding: 36px 40px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  min-width: 260px;
  max-width: 340px;
  text-align: center;
  box-shadow: 0 8px 32px rgba(23, 66, 131, 0.12);
  border: 1.5px solid #e8eef7;
  transition: border-color 0.4s;
}
.loading-box.loading-phase-1 { border-color: #ffe082; }
.loading-box.loading-phase-2 { border-color: #ffb74d; }
.loading-box.loading-phase-3 { border-color: #ef9a9a; }

/* ── 스피너 ── */
.loading-spinner {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}
.loading-spinner-inner {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  border: 4px solid transparent;
  animation: spin 0.9s linear infinite;
}
/* phase 0: 정상 — 파랑 */
.phase-normal .loading-spinner-inner {
  border-top-color: #174283;
  border-right-color: #c8d8ee;
}
/* phase 1: 느림 — 노랑 */
.phase-slow .loading-spinner-inner {
  border-top-color: #f4c430;
  border-right-color: #fff3c0;
  animation-duration: 1.1s;
}
/* phase 2: 지연 — 주황 */
.phase-delay .loading-spinner-inner {
  border-top-color: #e67e22;
  border-right-color: #fde8cc;
  animation-duration: 1.4s;
}
/* phase 3: 타임아웃 — 빨강 (느리게) */
.phase-timeout .loading-spinner-inner {
  border-top-color: #e03030;
  border-right-color: #fce4e4;
  animation-duration: 2s;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* ── 단계 인디케이터 (점 4개) ── */
.loading-steps {
  display: flex;
  gap: 8px;
  align-items: center;
}
.loading-step-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #e0e0e0;
  transition: background 0.3s, transform 0.3s;
}
.loading-step-dot.active   { background: #c8d8ee; }
.loading-step-dot.current  { background: #174283; transform: scale(1.35); }
.loading-phase-1 .loading-step-dot.current { background: #f4c430; }
.loading-phase-2 .loading-step-dot.current { background: #e67e22; }
.loading-phase-3 .loading-step-dot.current { background: #e03030; }

/* ── 메시지 ── */
.loading-message {
  font-size: 0.95em;
  color: #333;
  font-weight: 600;
  line-height: 1.5;
  margin: 0;
}
.loading-dots {
  display: inline-block;
  width: 18px;  /* 점이 바뀌어도 레이아웃 흔들리지 않도록 */
  text-align: left;
}
.loading-sub {
  font-size: 0.8em;
  color: #888;
  line-height: 1.65;
  margin: 0;
  white-space: pre-line;
}

/* ── 재시도 버튼 (phase 3) ── */
.loading-retry-btn {
  margin-top: 4px;
  padding: 9px 26px;
  border: 1.5px solid #e03030;
  border-radius: 20px;
  background: #fff;
  color: #e03030;
  font-size: 0.88em;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.18s, color 0.18s;
  font-family: inherit;
}
.loading-retry-btn:hover {
  background: #e03030;
  color: #fff;
}

