/* ── 로그인 페이지 — 회원가입 유도 영역 ── */
.login-join-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin-top: 14px;
}
.login-join-text {
  font-size: 0.82em;
  color: #888;
}
.login-join-btn {
  font-size: 0.82em;
  color: #174283;
  font-weight: 600;
  text-decoration: underline;
  cursor: pointer;
}
.login-join-btn:hover { color: #1565C0; }

/* ── MyPage — 이메일 인증완료 뱃지 ── */
.mp-email-ok {
  display: inline-flex;
  align-items: center;
  padding: 0 12px;
  height: 42px;
  background: #e8f5e9;
  color: #2e7d32;
  font-size: 0.82em;
  font-weight: 600;
  border-radius: 6px;
  white-space: nowrap;
  flex-shrink: 0;
}

/* ══════════════════════════════════════
   WishlistPanel — MyPage 임베드용 (compact)
══════════════════════════════════════ */

.wishlist-panel { width: 100%; }

.wishlist-panel-username {
  font-size: 0.88em;
  color: #555;
  margin-bottom: 12px;
}

.wishlist-panel-username.compact {
  font-size: 0.82em;
  color: #888;
  margin-bottom: 10px;
}

/* MyPage 찜목록 탭 — 내부 여백 줄임 */
.mypage-section--wishlist {
  padding: 16px 12px;
}

.mypage-section--wishlist .mylist-tabs {
  margin-bottom: 10px;
}

.mypage-section--wishlist .mylist-item {
  border-radius: 6px;
}

/* ══════════════════════════════════════
   WishlistPanel — 마감정보 없음 + 금융 표기
══════════════════════════════════════ */

/* 마감정보 없음 */
.mylist-deadline.no-deadline {
  color: #bbb;
  font-size: 0.75em;
  font-style: italic;
}

/* 금융 — 상품유형 표시 */
.mylist-deadline.fin-no-deadline {
  color: #888;
  font-size: 0.78em;
}

.mylist-deadline.fin-no-deadline strong {
  color: #C62828;
  font-weight: 600;
}

/* 금융 아이템 — 상품유형 + 상품명 서브 행 */
.mylist-finance-sub {
  display: flex;
  flex-direction: column;
  gap: 3px;
  margin: 4px 0 2px;
}

.finance-type-badge {
  display: inline-block;
  font-size: 0.72em;
  font-weight: 600;
  color: #C62828;
  background: #fff0f0;
  border: 1px solid #ffd0d0;
  border-radius: 4px;
  padding: 1px 7px;
  font-style: normal;
  width: fit-content;
}

.finance-prdtnm {
  font-size: 0.88em;
  color: #222;
  font-weight: 500;
  font-style: normal;
  line-height: 1.4;
}

/* 금융 찜 아이템 — 약간 다른 배경으로 구분 */
.mylist-item.finance-item-wish {
  background: #fffafa;
}

/* ── 금융 찜목록 — 은행명 뱃지 ── */
.mylist-finance-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  margin-bottom: 3px;
}

.finance-bank-badge {
  display: inline-block;
  font-size: 0.72em;
  font-weight: 600;
  color: #174283;
  background: #eef2fb;
  border: 1px solid #c5d3e8;
  border-radius: 4px;
  padding: 1px 7px;
  font-style: normal;
  width: fit-content;
}
