l_cont{ \n    display:  block;\n    background-color: transparent;\n\n}\n.detail .detail_cont li{\n\n   max-width:780px;\n   margin:10px auto;\n\n}   \n\n.detail .detail_cont li strong{ \n    display: block;\n    width: 150px;\n    padding: 15px 0px;\n    text-align: center;\n    background-color: #174283;\n    color:#fff;\n}\n.detail .detail_cont li p{\n\n    color:#878787;\n    padding: 0px 10px;\n    font-size: 0.9em;\n    flex:1;\n    text-align: left;\n    line-height: 1.5em;\n}\n\n.detail ul li{\n    \n    padding: 10px;\n    text-align: center;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    background-color: #fff;\n\n}\n\n.detail ul li strong{\n\n    color: #174283;\n    padding: 0px 8px;\n}\n\n\n/* Join */\n\n\n.join {\n\n    padding: 100px 0px;\n    margin:0 auto;\n\n}\n\n.join .joinBox{\n\n    background-color: #fff;\n    max-width:780px;\n    padding: 50px 20px;\n    margin:0 auto;\n}\n\n.join .joinBox h3{\n     text-align: center;\n     font-size: 0.8em;\n     color:#878787;\n     padding: 10px 0px;\n}\n\n.join .joinBox form{\n\n    max-width:680px;\n    margin:0 auto;\n    padding: 7px 0px;\n}\n\n\n.join .joinBox form input{\n\n    width: 200px;\n    height: 50px;\n    margin:5px;\n    font-size: 1em;\n    border-radius: 1px;\n    display: block;\n    color:#878787;\n    background-color: #f4f4f4;\n    border:2px solid #174283;\n    text-align: center;\n}\n\n.join .joinBox form button{\n\n    width: 100px;\n    height: 53px;\n    background-color: #174283;\n    color:#fff;\n    font-weight: 400;\n    font-size: 1em;\n    border:none;\n}\n\n.join .joinBox .submitBtn{\n\n    width: 248px;\n    height: 53px;\n    background-color: #174283;\n    color:#fff;\n    font-weight: 400;\n    border:none;\n    font-size: 1em;\n    margin: 0 auto;\n    display: block;\n}\n\n/* FormControl */\n\n.FormControl{\n\n     margin:0 auto;\n     padding: 0px 230px;\n\n}\n\n.FormControl label{\n    padding: 8px 0px;\n    font-size: 0.8em;\n    color:#878787;\n    margin:0 auto;\n}\n\n.FormControl label .required{\n    color:#f00000;\n    padding: 0px 5px;\n}\n\n\n.FormControl .error{\n\n    color:#f00000;\n    font-size: 0.7em;\n    padding: 8px 0px;\n    \n}\n\n\n/* MyList */\n\n/* ══════════════════════════════════════\n   찜목록 (MyList) — 새 디자인\n══════════════════════════════════════ */\n.mylist-wrap {\n  padding: 16px 16px 100px;\n  max-width: 600px;\n  margin: 0 auto;\n}\n.mylist-username {\n  font-size: 14px;\n  color: #174283;\n  font-weight: 600;\n  margin: 0 0 12px;\n}\n\n/* 미로그인 안내 */\n.mylist-login-notice {\n  text-align: center;\n  padding: 80px 20px;\n}\n.mylist-login-title {\n  font-size: 15px;\n  color: #555;\n  margin-bottom: 20px;\n}\n.mylist-login-btn {\n  padding: 10px 24px;\n  background: #174283;\n  color: #fff;\n  border: none;\n  border-radius: 8px;\n  font-size: 14px;\n  font-weight: 600;\n  cursor: pointer;\n}\n.mylist-login-btn:hover { background: #1565C0; }\n\n/* 카테고리 탭 */\n.mylist-tabs {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  margin-bottom: 14px;\n}\n.mylist-tab {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  padding: 5px 12px;\n  border: 1.5px solid #dde3ee;\n  border-radius: 20px;\n  background: #fff;\n  font-size: 13px;\n  color: #555;\n  cursor: pointer;\n  transition: all 0.18s;\n}\n.mylist-tab.active {\n  background: #174283;\n  border-color: #174283;\n  color: #fff;\n  font-weight: 600;\n}\n.mylist-tab-count {\n  background: rgba(0,0,0,0.12);\n  border-radius: 10px;\n  padding: 0 5px;\n  font-size: 11px;\n  min-width: 16px;\n  text-align: center;\n}\n.mylist-tab.active .mylist-tab-count { background: rgba(255,255,255,0.25); }\n\n/* 목록 */\n.mylist-list {\n  list-style: none;\n  padding: 0;\n  margin: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n.mylist-item {\n  display: flex;\n  align-items: stretch;\n  border: 1px solid #e5eaf3;\n  border-radius: 10px;\n  background: #fff;\n  overflow: hidden;\n  transition: box-shadow 0.18s;\n}\n.mylist-item:hover { box-shadow: 0 2px 10px rgba(23,66,131,0.10); }\n.mylist-item.expired {\n  opacity: 0.62;\n  background: #f7f7f8;\n  border-color: #d8d8d8;\n}\n\n.mylist-item-body {\n  flex: 1;\n  padding: 12px 14px;\n  cursor: pointer;\n  min-width: 0;\n}\n.mylist-item-top {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  margin-bottom: 5px;\n}\n.mylist-cat-badge {\n  display: inline-block;\n  padding: 2px 8px;\n  border-radius: 4px;\n  font-size: 11px;\n  font-weight: 700;\n  color: #fff;\n  white-space: nowrap;\n}\n.mylist-expired-badge {\n  font-size: 11px;\n  color: #999;\n  background: #eee;\n  border-radius: 4px;\n  padding: 1px 6px;\n}\n.mylist-item-title {\n  font-size: 14px;\n  font-weight: 500;\n  color: #222;\n  margin: 0 0 4px;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.mylist-deadline {\n  font-size: 12px;\n  color: #888;\n}\n.mylist-deadline.urgent { color: #d32f2f; font-weight: 600; }\n.mylist-deadline.past   { color: #aaa; text-decoration: line-through; }\n\n.mylist-delete-btn {\n  flex-shrink: 0;\n  width: 44px;\n  border: none;\n  background: transparent;\n  color: #bbb;\n  font-size: 16px;\n  cursor: pointer;\n  border-left: 1px solid #f0f0f0;\n  transition: color 0.15s, background 0.15s;\n}\n.mylist-delete-btn:hover { color: #e03030; background: #fff5f5; }\n\n.mylist-empty {\n  text-align: center;\n  padding: 60px 20px;\n  color: #aaa;\n  font-size: 14px;\n}\n\n/* ══════════════════════════════════════\n   종료된 공고 안내 (ExpiredNotice)\n══════════════════════════════════════ */\n.pol-gone {\n  text-align: center;\n  padding: 60px 24px 80px;\n}\n.pol-gone-title {\n  font-size: 18px;\n  font-weight: 700;\n  color: #333;\n  margin-bottom: 8px;\n}\n.pol-gone-name {\n  font-size: 14px;\n  color: #174283;\n  font-weight: 600;\n  margin-bottom: 12px;\n  word-break: keep-all;\n}\n.pol-gone-desc {\n  font-size: 13px;\n  color: #888;\n  line-height: 1.7;\n  margin-bottom: 28px;\n}\n.pol-gone-actions {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  align-items: center;\n}\n.pol-gone-btn {\n  padding: 11px 28px;\n  border-radius: 8px;\n  font-size: 14px;\n  font-weight: 600;\n  cursor: pointer;\n  border: 1.5px solid #174283;\n  background: transparent;\n  color: #174283;\n  width: 220px;\n  transition: background 0.18s, color 0.18s;\n}\n.pol-gone-btn.primary {\n  background: #174283;\n  color: #fff;\n}\n.pol-gone-btn:hover { background: #174283; color: #fff; }\n.pol-gone-btn.primary:hover { background: #1565C0; border-color: #1565C0; }\n\n\n/* dialog */\n\n.dialog{\n\n    background-color: rgba(0,0,0,.6);\n    position:fixed;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    left:0;\n    right:0;\n    top:0;\n    bottom:0;\n    z-index:1000;\n}\n.dialog .dialogBox{\n    width: 400px;\n    height:300px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    position: relative;\n    z-index:1100;\n    border-radius: 8px;\n    background-color: #fff;\n}\n\n.dialog .dialogBox > header{\n\n    font-size: 1.3em;\n    color:#174283;\n}\n\n.dialog .dialogBox > main {\n\n    color:#000;\n    font-size: 1em;\n    padding: 8px 0px;\n}\n\n.dialog .dialogBox > footer{\n\n    padding: 8px 0px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n}\n\n.dialog .dialogBox > footer button{\n\n    padding: 10px;\n    background-color: #f4f4f4;\n    color:#174283;\n    border-radius: 3px;\n    border:1px solid #174283;\n\n}\n\n.openPage{\n\n    background-color: #fff;\n    position:fixed;\n    z-index:1200;\n    left:0;\n    top:0;\n    right:0;\n    bottom:0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n\n}\n\n.openPage img{\n\n    height:30px;\n}\n\n/* ===== 개선: 빈 상태 & 로딩 상태 ===== */\n\n.info .list .listBox ul li.empty-state,\n.financeInfo .list .listBox ul li.empty-state {\n  text-align: center;\n  padding: 30px;\n  color: #878787;\n  font-size: 0.9em;\n}\n\n/* 신청 링크 스타일 */\n.detail .detail_cont li p a {\n  color: #174283;\n  text-decoration: underline;\n  word-break: break-all;\n}\n.detail .detail_cont li p a:hover {\n  color: #5a85c8;\n}\n\n/* 찜하기 버튼 강조 */\n.detail ul li:last-child {\n  cursor: pointer;\n  color: #174283;\n  font-weight: 600;\n  transition: color 0.2s;\n}\n.detail ul li:last-child:hover {\n  color: #e03030;\n}\n\n/* 반응형 기본 지원 */\n@media (max-width: 600px) {\n  .category {\n    padding: 20px 10px;\n  }\n  .category ul li {\n    width: 140px;\n    height: 60px;\n    margin: 7px;\n  }\n  .board {\n    padding: 20px 10px;\n  }\n  .info {\n    padding: 30px 0px 150px;\n  }\n  .info .list {\n    width: 95%;\n  }\n  .financeInfo .list {\n    width: 95%;\n  }\n  .detail ul {\n    flex-direction: column;\n  }\n  .join .joinBox {\n    padding: 30px 15px;\n  }\n  .FormControl {\n    padding: 0px 20px;\n  }\n  .title.active a::before {\n    left: 30px;\n  }\n}\n\n/* ===== 뒤로가기 버튼 ===== */\n.back-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  margin-bottom: 16px;\n  padding: 7px 14px;\n  background: #f4f7fb;\n  border: 1px solid #c8d8ee;\n  border-radius: 20px;\n  color: #174283;\n  font-size: 0.85em;\n  font-weight: 500;\n  cursor: pointer;\n  transition: background 0.18s, color 0.18s;\n}\n.back-btn:hover {\n  background: #174283;\n  color: #fff;\n}\n\n/* ===== 페이지네이션 ===== */\n.pagination {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 4px;\n  padding: 20px 0 10px;\n}\n.pagination button {\n  min-width: 34px;\n  height: 34px;\n  padding: 0 8px;\n  border: 1px solid #c8d8ee;\n  border-radius: 6px;\n  background: #fff;\n  color: #174283;\n  font-size: 0.88em;\n  cursor: pointer;\n  transition: background 0.15s, color 0.15s;\n}\n.pagination button:hover:not(:disabled) {\n  background: #174283;\n  color: #fff;\n  border-color: #174283;\n}\n.pagination button.active {\n  background: #174283;\n  color: #fff;\n  border-color: #174283;\n  font-weight: 700;\n}\n.pagination button:disabled {\n  opacity: 0.35;\n  cursor: default;\n}\n.pagination .ellipsis {\n  padding: 0 4px;\n  color: #878787;\n  font-size: 0.9em;\n  line-height: 34px;\n}\n\n/* ===== 목록 총 건수 표시 ===== */\n.list_title {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n.list_count {\n  font-size: 0.8em;\n  color: #878787;\n  font-weight: 400;\n  text-align: right;\n  width: 100%;\n}\n\n/* ===== Board 정렬 탭 & 툴바 ===== */\n.board-toolbar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  width:90%;\n  margin:0 auto;\n  padding-bottom:10px;\n}\n.board-sort-tabs {\n  display: flex;\n  gap: 6px;\n}\n.sort-tab {\n  padding: 5px 14px;\n  border: 1px solid #c8d8ee;\n  border-radius: 20px;\n  background: #fff;\n  color: #555;\n  font-size: 0.83em;\n  cursor: pointer;\n  transition: background 0.15s, color 0.15s, border-color 0.15s;\n  min-width:100px;\n}\n.sort-tab.active {\n  background: #174283;\n  color: #fff;\n  border-color: #174283;\n  font-weight: 600;\n}\n.sort-tab:hover:not(.active) {\n  background: #f0f4fb;\n  border-color: #174283;\n  color: #174283;\n}\n.board-total {\n  font-size: 0.8em;\n  color: #878787;\n}\n\n/* Board 목록 아이템 메타 정보 */\n.board-meta {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin-top: 3px;\n}\n.board-meta em {\n  font-style: normal;\n  font-size: 0.8em;\n  color: #878787;\n}\n.board-date {\n  color: #c0392b !important;\n  font-weight: 500;\n}\n\n/* Board 빈 상태 */\n.board-empty {\n  text-align: center;\n  padding: 30px;\n  color: #878787;\n  font-size: 0.9em;\n  list-style: none;\n}\n\n/* ===== FinanceInfo 리스트 아이템 전체 클릭 ===== */\n.finance-item {\n  cursor: pointer;\n  /* display: flex;\n  flex-direction: column; */\n  gap: 3px;\n  /* padding: 12px 16px !important; */\n  padding: 12px 0px !important;\n  transition: background 0.15s;\n}\n.finance-item:hover {\n  background: #f0f4fb;\n}\n.finance-bank {\n  font-size: 0.8em;\n  color: #878787;\n}\n.finance-prdtnm {\n  font-size: 0.95em;\n  font-weight: 600;\n  color: #174283;\n}\n.finance-sub {\n  display: flex;\n  gap: 10px;\n  margin-top: 2px;\n}\n.finance-sub em {\n  font-style: normal;\n  font-size: 0.78em;\n  color: #aaa;\n}\n\n/* ===== 금융 툴바 (정렬 탭 + 총 건수) ===== */\n.finance-toolbar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0 4px;\n  margin-bottom: 8px;\n  width:100%;\n}\n\n/* 금리 표시 색상 */\n.rate-saving {\n  color: #32a883 !important;\n  font-weight: 600 !important;\n}\n.rate-loan {\n  color: #c0392b !important;\n  font-weight: 600 !important;\n}\n\n/* ══════════════════════════════════════\n   금융 상품 상세 페이지 (FinDetail)\n   ══════════════════════════════════════ */\n\n.fin-detail { padding-bottom: 40px; }\n\n/* 헤더 */\n.fin-header {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin-bottom: 4px;\n}\n.fin-badge {\n  display: inline-block;\n  padding: 2px 10px;\n  border-radius: 20px;\n  background: #174283;\n  color: #fff;\n  font-size: 0.75em;\n  font-weight: 600;\n  letter-spacing: 0.02em;\n}\n.fin-badge-sub {\n  display: inline-block;\n  padding: 2px 10px;\n  border-radius: 20px;\n  background: #e8eef7;\n  color: #174283;\n  font-size: 0.75em;\n  font-weight: 600;\n  margin-right: 4px;\n}\n.fin-pension-badges { margin-bottom: 10px; }\n.fin-bank { font-size: 0.85em; color: #878787; }\n.fin-title {\n  font-size: 1.1em;\n  font-weight: 700;\n  color: #222;\n  margin: 6px 0 14px;\n  line-height: 1.4;\n}\n\n/* 하이라이트 박스 (최고금리 / 최저금리) */\n.fin-highlight {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 4px;\n  padding: 18px 16px;\n  border-radius: 12px;\n  background: linear-gradient(135deg, #eaf1fb, #dde8f7);\n  border: 1px solid #c4d8f0;\n  margin-bottom: 18px;\n  text-align: center;\n}\n.fin-hl-label {\n  font-size: 0.78em;\n  color: #555;\n  font-weight: 500;\n}\n.fin-hl-rate {\n  font-size: 2em;\n  font-weight: 800;\n  line-height: 1.1;\n}\n.fin-hl-rate.saving { color: #174283; }\n.fin-hl-rate.loan   { color: #c0392b; }\n.fin-hl-note {\n  font-size: 0.72em;\n  color: #878787;\n}\n\n/* 섹션 */\n.fin-section {\n  border-top: 1px solid #eee;\n  padding: 16px 0 4px;\n  margin-bottom: 6px;\n}\n.fin-section-title {\n  font-size: 0.88em;\n  font-weight: 800;\n  color: #174283;\n  margin: 0 0 12px;\n}\n.fin-section-body { font-size: 0.88em; }\n\n/* 정보 행 */\n.fin-info-row {\n  display: flex;\n  gap: 10px;\n  padding: 7px 0;\n  border-bottom: 1px solid #f4f4f4;\n  align-items: flex-start;\n}\n.fin-label {\n  flex-shrink: 0;\n  width: 110px;\n  color: #878787;\n  font-size: 0.85em;\n}\n.fin-value {\n  flex: 1;\n  color: #222;\n  line-height: 1.5;\n  word-break: break-all;\n}\n\n/* 금리 테이블 */\n.fin-table-wrap {\n  overflow-x: auto;\n  margin-bottom: 8px;\n  border-radius: 8px;\n  border: 1px solid #e0e8f4;\n}\n.fin-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 0.82em;\n}\n.fin-table th {\n  background: #f0f4fb;\n  color: #174283;\n  font-weight: 600;\n  padding: 8px 10px;\n  text-align: center;\n  white-space: nowrap;\n  border-bottom: 1px solid #dde8f7;\n}\n.fin-table td {\n  padding: 7px 10px;\n  text-align: center;\n  border-bottom: 1px solid #f4f4f4;\n  color: #333;\n  white-space: nowrap;\n}\n.fin-table tr:last-child td { border-bottom: none; }\n.fin-table tr:hover td { background: #f8fafd; }\n\n/* 금리 셀 강조 */\n.rate-cell        { font-weight: 600; color: #333; }\n.rate-cell.best   { color: #174283; }\n.rate-cell.avg    { color: #2980b9; }\n\n/* 서브 노트 */\n.fin-sub-note {\n  margin-top: 8px;\n  font-size: 0.8em;\n  color: #555;\n  padding: 6px 10px;\n  background: #f8f8f8;\n  border-radius: 6px;\n}\n.fin-sub-note.warn { background: #fff5f5; color: #c0392b; }\n.fin-sub-note em   { color: #aaa; font-style: normal; }\n\n/* 긴 텍스트 */\n.fin-long-text {\n  font-size: 0.84em;\n  color: #444;\n  line-height: 1.7;\n  white-space: pre-line;\n}\n\n/* 개인신용대출 신용등급 그리드 */\n.fin-grade-desc {\n  font-size: 0.82em;\n  color: #666;\n  margin-bottom: 12px;\n  line-height: 1.6;\n}\n.fin-grade-desc em { color: #174283; font-style: normal; }\n.fin-grade-group   { margin-bottom: 14px; }\n.fin-grade-type-label {\n  font-size: 0.8em;\n  color: #174283;\n  font-weight: 600;\n  margin-bottom: 8px;\n  padding: 4px 10px;\n  background: #eaf1fb;\n  border-radius: 6px;\n  display: inline-block;\n}\n.fin-grade-grid {\n  display: grid;\n  grid-template-columns: repeat(5, 1fr);\n  gap: 6px;\n}\n.fin-grade-cell {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 3px;\n  padding: 8px 4px;\n  border-radius: 8px;\n  border: 1px solid #e0e8f4;\n}\n.fin-grade-cell.grade-good { background: #eaf4ea; border-color: #b2ddb2; }\n.fin-grade-cell.grade-mid  { background: #fff9e6; border-color: #ffe082; }\n.fin-grade-cell.grade-low  { background: #fef0f0; border-color: #f9c0c0; }\n.grade-label { font-size: 0.72em; color: #888; }\n.grade-rate  { font-size: 0.9em; font-weight: 700; color: #222; }\n.fin-grade-cell.grade-good .grade-rate { color: #27ae60; }\n.fin-grade-cell.grade-mid  .grade-rate { color: #e67e22; }\n.fin-grade-cell.grade-low  .grade-rate { color: #c0392b; }\n\n/* 빈 상태 */\n.fin-empty   { text-align: center; padding: 50px; color: #878787; }\n.fin-no-data { color: #aaa; font-size: 0.83em; padding: 12px 0; }\n\n/* 공시 기간 */\n.fin-period {\n  font-size: 0.78em;\n  color: #aaa;\n  text-align: center;\n  padding: 14px 0 6px;\n  border-top: 1px solid #f0f0f0;\n  margin-top: 10px;\n}\n\n/* 찜하기 */\n.fin-wishlist {\n  text-align: center;\n  padding: 14px;\n  color: #174283;\n  font-weight: 600;\n  cursor: pointer;\n  font-size: 0.95em;\n  transition: color 0.2s;\n}\n.fin-wishlist:hover { color: #e03030; }\n.fin-wishlist.active { color: #e03030; font-weight: 700; }\n.fin-wishlist.active:hover { color: #174283; }\n\n/* 반응형 — 신용등급 그리드 좁은 화면 */\n@media (max-width: 600px) {\n  .fin-grade-grid { grid-template-columns: repeat(5, 1fr); gap: 4px; }\n  .fin-grade-cell { padding: 6px 2px; }\n  .grade-label    { font-size: 0.65em; }\n  .grade-rate     { font-size: 0.82em; }\n  .fin-table      { font-size: 0.75em; }\n}\n\n/* ══════════════════════════════════════\n   정책 리스트 (Info)\n   ══════════════════════════════════════ */\n.policy-item {\n  cursor: pointer;\n  padding: 12px 14px !important;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  transition: background 0.15s;\n}\n.policy-item:hover  { background: #f0f4fb; }\n.policy-item.expired { opacity: 0.5; }\n\n.policy-title {\n  font-size: 0.93em;\n  font-weight: 600;\n  color: #222;\n  line-height: 1.4;\n}\n.policy-desc {\n  font-size: 0.8em;\n  color: #888;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  margin: 0;\n}\n.policy-deadline {\n  font-size: 0.75em!important;\n  color: #aaa!important;\n}\n.policy-deadline.urgent { color: #c0392b; font-weight: 700; }\n.policy-deadline.past   { color: #bbb; }\n.policy-empty {\n  text-align: center;\n  padding: 30px;\n  color: #878787;\n  font-size: 0.9em;\n  list-style: none;\n}\n\n/* ══════════════════════════════════════\n   정책 상세 페이지 (Detail)\n   ══════════════════════════════════════ */\n.pol-detail { padding-bottom: 40px; }\n\n.pol-header {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin-bottom: 4px;\n}\n.pol-badge {\n  display: inline-block;\n  padding: 2px 10px;\n  border-radius: 20px;\n  background: #174283;\n  color: #fff;\n  font-size: 0.75em;\n  font-weight: 600;\n}\n.pol-org {\n  font-size: 0.83em;\n  color: #878787;\n}\n.pol-title {\n  font-size: 1.05em;\n  font-weight: 700;\n  color: #222;\n  margin: 6px 0 14px;\n  line-height: 1.5;\n}\n\n/* 마감 임박/종료 배너 */\n.pol-urgent {\n  background: #fff5f5;\n  border: 1px solid #f9c0c0;\n  border-radius: 8px;\n  padding: 10px 14px;\n  font-size: 0.85em;\n  color: #c0392b;\n  margin-bottom: 14px;\n}\n.pol-expired {\n  background: #f5f5f5;\n  border: 1px solid #ddd;\n  border-radius: 8px;\n  padding: 10px 14px;\n  font-size: 0.85em;\n  color: #999;\n  margin-bottom: 14px;\n}\n\n/* 섹션 */\n.pol-section {\n  border-top: 1px solid #eee;\n  padding: 14px 0 6px;\n  margin-bottom: 4px;\n}\n.pol-section-title {\n  font-size: 0.87em;\n  font-weight: 800;\n  color: #174283;\n  margin: 0 0 10px;\n}\n.pol-section-body { font-size: 0.87em; }\n\n/* 정보 행 */\n.pol-info-row {\n  display: flex;\n  gap: 10px;\n  padding: 6px 0;\n  border-bottom: 1px solid #f4f4f4;\n  align-items: flex-start;\n}\n.pol-info-row.highlight { background: #fafbff; border-radius: 4px; padding: 6px 4px; }\n.pol-label {\n  flex-shrink: 0;\n  width: 90px;\n  color: #878787;\n  font-size: 0.85em;\n}\n.pol-value {\n  flex: 1;\n  color: #222;\n  line-height: 1.5;\n  word-break: break-all;\n}\n\n/* 기간 */\n.pol-period-row {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  font-size: 0.9em;\n  color: #333;\n  padding: 4px 0;\n}\n.pol-period-sep { color: #ccc; }\n.pol-date-urgent { color: #c0392b; font-weight: 700; }\n\n/* 링크 */\n.pol-link {\n  display: block;\n  padding: 10px 14px;\n  border-radius: 8px;\n  border: 1px solid #c8d8ee;\n  color: #174283;\n  font-size: 0.85em;\n  font-weight: 600;\n  margin-bottom: 8px;\n  text-decoration: none;\n  transition: background 0.15s;\n}\n.pol-link:hover { background: #f0f4fb; }\n.pol-link.primary {\n  background: #174283;\n  color: #fff;\n  border-color: #174283;\n}\n.pol-link.primary:hover { background: #1a55a8; }\n\n/* 긴 텍스트 */\n.pol-long-text {\n  font-size: 0.85em;\n  color: #444;\n  line-height: 1.75;\n  white-space: pre-line;\n  word-break: break-all;\n}\n\n/* 찜하기 */\n.pol-wishlist {\n  text-align: center;\n  padding: 14px;\n  color: #174283;\n  font-weight: 600;\n  cursor: pointer;\n  font-size: 0.95em;\n  border-top: 1px solid #f0f0f0;\n  margin-top: 10px;\n  transition: color 0.2s;\n}\n.pol-wishlist:hover { color: #e03030; }\n.pol-wishlist.active { color: #e03030; font-weight: 700; }\n.pol-wishlist.active:hover { color: #174283; }\n.pol-empty {\n  text-align: center;\n  padding: 50px;\n  color: #878787;\n  font-size: 0.9em;\n}\n\n/* ══════════════════════════════════════\n   검색 바 (Info / Board 공통)\n   ══════════════════════════════════════ */\n.search-bar {\n  position: relative;\n  width: 90%;\n  margin: 16px auto 8px;\n  display: flex;\n  align-items: center;\n}\n.board-search {\n  width: 90%;\n  margin: 0 auto 12px;\n}\n.search-input {\n  width: 100%;\n  height: 42px;\n  padding: 0 40px 0 16px;\n  border: 1.5px solid #c8d8ee;\n  border-radius: 21px;\n  font-size: 0.88em;\n  color: #333;\n  background: #fff;\n  outline: none;\n  box-sizing: border-box;\n  transition: border-color 0.18s, box-shadow 0.18s;\n  font-family: inherit;\n}\n.search-input:focus {\n  border-color: #174283;\n  box-shadow: 0 0 0 3px rgba(23, 66, 131, 0.1);\n}\n.search-input::placeholder {\n  color: #b0b8c8;\n}\n.search-clear {\n  position: absolute;\n  right: 12px;\n  background: none;\n  border: none;\n  color: #aaa;\n  font-size: 0.88em;\n  cursor: pointer;\n  padding: 4px;\n  line-height: 1;\n  transition: color 0.15s;\n}\n.search-clear:hover {\n  color: #174283;\n}\n\n/* ══════════════════════════════════════\n   LoadingDialog — 시간 기반 로딩 UI\n   ══════════════════════════════════════ */\n\n/* 오버레이 */\n.loading-overlay {\n  position: fixed;\n  inset: 0;\n  background: rgba(0, 0, 0, 0.52);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  z-index: 1000;\n}\n\n/* 카드 */\n.loading-box {\n  background: #fff;\n  border-radius: 20px;\n  padding: 36px 40px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 16px;\n  min-width: 260px;\n  max-width: 340px;\n  text-align: center;\n  box-shadow: 0 8px 32px rgba(23, 66, 131, 0.12);\n  border: 1.5px solid #e8eef7;\n  transition: border-color 0.4s;\n}\n.loading-box.loading-phase-1 { border-color: #ffe082; }\n.loading-box.loading-phase-2 { border-color: #ffb74d; }\n.loading-box.loading-phase-3 { border-color: #ef9a9a; }\n\n/* ── 스피너 ── */\n.loading-spinner {\n  width: 52px;\n  height: 52px;\n  border-radius: 50%;\n  position: relative;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n.loading-spinner-inner {\n  width: 100%;\n  height: 100%;\n  border-radius: 50%;\n  border: 4px solid transparent;\n  animation: spin 0.9s linear infinite;\n}\n/* phase 0: 정상 — 파랑 */\n.phase-normal .loading-spinner-inner {\n  border-top-color: #174283;\n  border-right-color: #c8d8ee;\n}\n/* phase 1: 느림 — 노랑 */\n.phase-slow .loading-spinner-inner {\n  border-top-color: #f4c430;\n  border-right-color: #fff3c0;\n  animation-duration: 1.1s;\n}\n/* phase 2: 지연 — 주황 */\n.phase-delay .loading-spinner-inner {\n  border-top-color: #e67e22;\n  border-right-color: #fde8cc;\n  animation-duration: 1.4s;\n}\n/* phase 3: 타임아웃 — 빨강 (느리게) */\n.phase-timeout .loading-spinner-inner {\n  border-top-color: #e03030;\n  border-right-color: #fce4e4;\n  animation-duration: 2s;\n}\n\n@keyframes spin {\n  to { transform: rotate(360deg); }\n}\n\n/* ── 단계 인디케이터 (점 4개) ── */\n.loading-steps {\n  display: flex;\n  gap: 8px;\n  align-items: center;\n}\n.loading-step-dot {\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  background: #e0e0e0;\n  transition: background 0.3s, transform 0.3s;\n}\n.loading-step-dot.active   { background: #c8d8ee; }\n.loading-step-dot.current  { background: #174283; transform: scale(1.35); }\n.loading-phase-1 .loading-step-dot.current { background: #f4c430; }\n.loading-phase-2 .loading-step-dot.current { background: #e67e22; }\n.loading-phase-3 .loading-step-dot.current { background: #e03030; }\n\n/* ── 메시지 ── */\n.loading-message {\n  font-size: 0.95em;\n  color: #333;\n  font-weight: 600;\n  line-height: 1.5;\n  margin: 0;\n}\n.loading-dots {\n  display: inline-block;\n  width: 18px;  /* 점이 바뀌어도 레이아웃 흔들리지 않도록 */\n  text-align: left;\n}\n.loading-sub {\n  font-size: 0.8em;\n  color: #888;\n  line-height: 1.65;\n  margin: 0;\n  white-space: pre-line;\n}\n\n/* ── 재시도 버튼 (phase 3) ── */\n.loading-retry-btn {\n  margin-top: 4px;\n  padding: 9px 26px;\n  border: 1.5px solid #e03030;\n  border-radius: 20px;\n  background: #fff;\n  color: #e03030;\n  font-size: 0.88em;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background 0.18s, color 0.18s;\n  font-family: inherit;\n}\n.loading-retry-btn:hover {\n  background: #e03030;\n  color: #fff;\n}\n\n/* ══════════════════════════════════════\n   LH / SH 공통 + 개별 스타일\n   ══════════════════════════════════════ */\n\n/* ── 공통 래퍼 ── */\n.lh-wrap,\n.sh-wrap {\n  padding: 0 0 40px;\n  min-height: 100%;\n}\n\n/* ── 상단 배너 ── */\n.lh-banner,\n.sh-banner {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 6px;\n  padding: 22px 20px 18px;\n  margin-bottom: 4px;\n}\n.lh-banner { background: linear-gradient(135deg, #003D7C 0%, #1565C0 100%); }\n.sh-banner  { background: linear-gradient(135deg, #1B5E20 0%, #2E7D32 100%); }\n\n.lh-badge,\n.sh-badge {\n  font-size: 1.05em;\n  font-weight: 800;\n  letter-spacing: 2px;\n  padding: 4px 14px;\n  border-radius: 20px;\n  border: 2px solid rgba(255,255,255,0.5);\n  color: #fff;\n}\n.lh-banner p, .sh-banner p {\n  margin: 0;\n  font-size: 0.95em;\n  font-weight: 600;\n  color: #fff;\n}\n.lh-sub, .sh-sub {\n  font-size: 0.75em;\n  color: rgba(255,255,255,0.75);\n}\n\n/* ── 검색바 오버라이드 ── */\n.lh-search,\n.sh-search {\n  width: 90%;\n  margin: 14px auto 6px;\n}\n\n/* ── 툴바 ── */\n.lh-toolbar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0 16px 8px;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n\n/* ── 목록 ── */\n.lh-list {\n  list-style: none;\n  padding: 0 12px;\n  margin: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.lh-item {\n  background: #fff;\n  border: 1.5px solid #e0eaf6;\n  border-radius: 12px;\n  padding: 14px 16px;\n  cursor: pointer;\n  transition: border-color 0.18s, box-shadow 0.18s, opacity 0.18s;\n}\n.lh-item:hover {\n  border-color: #174283;\n  box-shadow: 0 4px 14px rgba(23, 66, 131, 0.10);\n}\n.lh-item.expired {\n  opacity: 0.55;\n}\n\n.lh-item-top {\n  display: fl